I already use it and it works great, however, as stated above - by using private API. When this MR is merged, my private API usage can be removed too.

You can do something along these lines:

```
if (instanceConstructor.ɵcmp) {
  // Using private API until the corresponding Angular issues are resolved.
  // Issues:  https://github.com/angular/angular/issues/31495, https://github.com/angular/angular/issues/30497
  // PR:      https://github.com/angular/angular/pull/35464
  destroy = <Function>instanceConstructor.ɵcmp.onDestroy ?? noop;
  instanceConstructor.ɵcmp.onDestroy = __takeUntilDestroy__destroy__;
} else {
  destroy = <Function>instanceConstructor.prototype.ngOnDestroy ?? noop;
  instanceConstructor.prototype.ngOnDestroy = __takeUntilDestroy__destroy__;
}

function __takeUntilDestroy__destroy__() {
  destroy.call(this);
  // do something fancy
}
```

@kara the following snippet is the decorator code which no longer works for our team, along with a usage example.

### Decorator:
````ts
// NgUnsubscribe (Yes, we're terrible for using the Ng prefix)

import { Subject, Observable } from 'rxjs';

export interface NgUnsubscribe {
  readonly ngUnsubscribe: Observable<void>;
}

export function NgUnsubscribe() {
  return function(constructor) {
    const originalNgOnDestroy = constructor.prototype.ngOnDestroy;

    if (constructor.prototype.__hasSetupNgUnsubscribe) {
      // Handles errors that arise from using the decorator on inherited component classes.
      throw new Error(
        `${constructor.name} used @NgUnsubscribe already. Remove the decorator from ${constructor.name}`
      );
    }
    constructor.prototype.__hasSetupNgUnsubscribe = true;

    // Actually sets up the observable.
    Object.defineProperty(constructor.prototype, 'ngUnsubscribe', {
      get() {
        if (!this.__ngUnsubscribe) {
          this.__ngUnsubscribe = new Subject<void>();
        }
        return this.__ngUnsubscribe;
      }
    });

    // Do the unsubscription
    constructor.prototype.ngOnDestroy = function() {
      try {
        if (originalNgOnDestroy && typeof originalNgOnDestroy === 'function') {
          originalNgOnDestroy.apply(this, arguments);
        }
        if (this.__ngUnsubscribe) {
          const ngUnsubscribe = this.__ngUnsubscribe;
          ngUnsubscribe.next();
          ngUnsubscribe.complete();
          ngUnsubscribe.unsubscribe();
        }
      } catch {}
    };
  };
}


`````

### In Use:
````ts

@Injectable()
export class LogService {

   logNgUnsubscribeEmitted() {
   }

   logNgOnDestroyCalled() {
   }

}


@Component({
selector: 'foo-bar',
template: '',
styles: []
})
@NgUnsubscribe()
export class FooBarComponent implements OnInit, NgUnsubscribe {
   readonly ngUnsubscribe: Observable<void>;

   constructor(private _log: LogService) {}

   ngOnInit() {
       this.ngUnsubscribe.subscribe(() => this._log.logNgUnsubscribeEmitted());
   }

   ngOnDestroy() {
      this._log.logNgOnDestroyCalled();
   }
}



````

I'm no pro at writing tests, but the test would assert
 - That you can create and initialize FooBarComponent without errors
 - That when FooBarComponent is destroyed, both `logNgUnsubscribeEmitted` and `logNgOnDestroyCalled` have been called once.


That only uses `ngOnInit` and `ngOnDestroy`. To get a full sense of the usage, you could use the following decorator in a test environment.

````ts
export interface Mocks {
  onNgOnChanges: () => void;
  onNgOnInit: () => void;
  onNgOnDoCheck: () => void;
  onNgAfterContentInit: () => void;
  onNgAfterContentChecked: () => void;
  onNgAfterViewInit: () => void;
  onNgAfterViewChecked: () => void;
  onNgOnDestroy: () => void; 
}

const MOCKS: Mocks = null;

export function setTestMocks(mocks: Mocks) {
    MOCKS = mocks;
}


export function AugmentComponentHooks() {
   return function augmentComponentHooksDecorator(Original) {
    const originalNgOnChanges = Original.prototype.ngOnChanges;
    const originalNgOnInit = Original.prototype.ngOnInit;
    const originalNgOnDoCheck = Original.prototype.ngOnDoCheck;
    const originalNgAfterContentInit = Original.prototype.ngAfterContentInit;
    const originalNgAfterContentChecked = Original.prototype.ngAfterContentChecked;
    const originalNgAfterViewInit = Original.prototype.ngAfterViewInit;
    const originalNgAfterViewChecked = Original.prototype.ngAfterViewChecked;
    const originalNgOnDestroy = Original.prototype.ngOnDestroy;

    if (originalNgOnChanges) {
        Original.prototype.ngOnChanges = function(...args: Array<any>) {
            originalNgOnChanges.apply(this, arguments);
            MOCKS.onNgOnChanges();
        };
    }
    if (originalNgOnInit) {
        Original.prototype.ngOnInit = function(...args: Array<any>) {
            originalNgOnInit.apply(this, arguments);
            MOCKS.onNgOnInit();
        };
    }
    if (originalNgOnDoCheck) {
        Original.prototype.ngOnDoCheck = function(...args: Array<any>) {
            originalNgOnDoCheck.apply(this, arguments);
            MOCKS.onNgOnDoCheck();
        };
    }
    if (originalNgAfterContentInit) {
        Original.prototype.ngAfterContentInit = function(...args: Array<any>) {
            originalNgAfterContentInit.apply(this, arguments);
            MOCKS.onNgAfterContentInit();
        };
    }
    if (originalNgAfterContentChecked) {
        Original.prototype.ngAfterContentChecked = function(...args: Array<any>) {
            originalNgAfterContentChecked.apply(this, arguments);
            MOCKS.onNgAfterContentChecked();
        };
    }
    if (originalNgAfterViewInit) {
        Original.prototype.ngAfterViewInit = function(...args: Array<any>) {
            originalNgAfterViewInit.apply(this, arguments);
            MOCKS.onNgAfterViewInit();
        };
    }
    if (originalNgAfterViewChecked) {
        Original.prototype.ngAfterViewChecked = function(...args: Array<any>) {
            originalNgAfterViewChecked.apply(this, arguments);
            MOCKS.onNgAfterViewChecked();
        };
    }
    if (originalNgOnDestroy) {
        Original.prototype.ngOnDestroy = function(...args: Array<any>) {
            originalNgOnDestroy.apply(this, arguments);
            MOCKS.onNgOnDestroy();
        };
    }




   }
}


@Component({
    selector: 'uses-augmented-component',
    template: ``,
    styles: []
})
@AugmentComponentHooks()
export class UsesAugmentedComponent {

}

````

I realize that the team might want to implement another way of augmenting the lifecycle hooks - If there was another method, perhaps another compiler API we called in order to agument the hooks at runtime or compile time, that would be sufficient for me.

I don't think we really care about patching the prototype specifically - I think we care more about being able to augment the behavior using the convenient syntax Decorators provide.

